$(document).ready(function () {

    // Menu
    function initDropdowns() {
        $('.has-dropdown').off('mouseenter mouseleave click');

        if (window.innerWidth > 992) {
            $('.has-dropdown').hover(function () {
                $(this).toggleClass('has-dropdown--active');
            });
        } else {
            $('.has-dropdown').on('click', function () {
                $(this).toggleClass('has-dropdown--active');
            });
        }
    }

    initDropdowns();

    $(window).resize(function () {
        initDropdowns();
    });

    $('.burger').click(function () {
        $(this).toggleClass('burger--active')
        $('.header__list').toggleClass('header__list--active')
        $('body').toggleClass('fixed-body')
    })

    // Tabs
    $(".tab").hover(function () {
        let path = $(this).attr("data-tab-path")
        $(this).siblings(".tab").removeClass("tab--active")
        $(this).addClass("tab--active")

        $(this).parents(".tabs-inner").find(".tab__content").removeClass("tab__content--active")
        $(this).parents(".tabs-inner").find(`.tab__content[data-content-path="${path}"]`).addClass("tab__content--active")
    })

    // Custom-select
    $('.custom-select').each(function () {
        let $select = $(this);

        $select.find('.select-selected').on('click', function (e) {
            e.stopPropagation();

            $('.custom-select').not($select).removeClass('open');

            $select.toggleClass('open');
        });

        $select.find('.select-item').on('click', function () {
            let $item = $(this);
            let $clone = $item.clone();

            $select.find('.select-item').removeClass('is-active');
            $item.addClass('is-active');

            $select.find('.select-selected').html($clone);

            $select.removeClass('open');

            $select.trigger('change', [$item.data()]);
        });
    });

    $(document).on('click', function () {
        $('.custom-select').removeClass('open');
    });

    // Accordion
    $(".item:first").addClass("item--active");
    $(".item:first .item-hidden").show();

    $(".item-show").on("click", function () {
        const item = $(this).parents(".item");

        $(".item").not(item).removeClass("item--active");
        $(".item").not(item).find(".item-hidden").slideUp();

        item.toggleClass("item--active");
        item.find(".item-hidden").slideToggle();
    });

    // Up
    var e = $(".up");

    function t() {
        $(".modal--active video").each(function () {
            this.pause();
            this.currentTime = 0;
        });

        $(".modal").removeClass("modal--active");
        $("body").removeClass("fixed-body");
    }

    $(window).scroll(function () {
        if ($(window).scrollTop() > 300) {
            e.addClass("up--active");
        } else {
            e.removeClass("up--active");
        }
    });

    e.on("click", function (e) {
        e.preventDefault();

        $("html, body").animate(
            {
                scrollTop: 0
            },
            300
        );
    });

})

// Animation
gsap.registerPlugin(ScrollTrigger);

// Main
gsap.utils.toArray(".main__inner").forEach((section) => {

    gsap.from(section, {
        y: 80,
        opacity: 0,
        duration: 1.5,
        ease: "power3.out",
        scrollTrigger: {
            trigger: section,
            start: "top 75%",
            once: true
        }
    });

});

// SectionTop
gsap.utils.toArray(".section-top").forEach((section) => {

    gsap.from(section, {
        y: 80,
        opacity: 0,
        duration: 1.5,
        ease: "power3.out",
        scrollTrigger: {
            trigger: section,
            start: "top 75%",
            once: true
        }
    });

});

// bout-advantage
if (window.innerWidth >= 993) {
    const cards = gsap.utils.toArray('.about-advantage__card');

    const orderedCards = [
        cards[0],
        cards[1],
        cards[3],
        cards[2],
    ].filter(Boolean);

    const tl = gsap.timeline({
        scrollTrigger: {
            trigger: '.about-advantages__cards',
            start: 'top 50%',
            once: true,
        }
    });

    orderedCards.forEach((card, index) => {
        const arrow = card.querySelector('.arrow');

        gsap.set(card, {
            opacity: 0,
            y: 80
        });

        let arrowAnimation = {
            opacity: 0,
            x: 0,
            y: 0
        };

        switch (index) {
            case 0: 
                arrowAnimation.x = -60;
                break;

            case 1: 
                arrowAnimation.y = -60;
                break;

            case 2: 
                arrowAnimation.x = 60;
                break;

            case 3: 
                arrowAnimation.y = 60;
                break;
        }

        if (arrow) {
            gsap.set(arrow, arrowAnimation);
        }

        tl.to(card, {
            opacity: 1,
            y: 0,
            duration: 0.8,
            ease: 'power3.out'
        });

        if (arrow) {
            tl.to(arrow, {
                opacity: 1,
                x: 0,
                y: 0,
                duration: 0.45,
                ease: 'power3.out'
            }, '-=0.15');
        }
    });
}

if (window.innerWidth <= 992) {
    document.addEventListener("DOMContentLoaded", () => {

        const cards = document.querySelectorAll(".about-advantage__card");

        cards.forEach((card) => {
            gsap.set(card, {
                opacity: 0,
                y: 80
            });

            gsap.to(card, {
                opacity: 1,
                y: 0,
                duration: 1,
                ease: "power3.out",
                scrollTrigger: {
                    trigger: card,
                    start: "top 85%",
                    toggleActions: "play none none reverse"
                }
            });
        });
    });
}

// Modification
if (window.innerWidth >= 993) {
    const tl = gsap.timeline({
        scrollTrigger: {
            trigger: ".modification__items",
            start: "top 70%",
            toggleActions: "play none none reverse"
        }
    });

    const arrows = gsap.utils.toArray(".modification__item-arrow");

    tl.from(arrows, {
        x: -120,        
        opacity: 0,
        duration: 0.8,
        ease: "power3.out",
        stagger: 1       
    });
}





